svg.script:
//
(function () {
  var svg = document.getElementById('beam-bd');
  if (!svg) return;

  var DESCS = {
    beam:    ['Cantilever Beam',           '300 mm steel ruler, 270 mm free, 25 mm wide, ~1 mm thick. E = 200 GPa, I ≈ 2.15×10⁻¹² m⁴.'],
    strain:  ['Strain Gauge + Amplifier',  'Foil gauge near fixed end; amp: 0–5 V centred at 2.5 V rest. ADC-read on A0 at ~100 Hz.'],
    accel:   ['MPU6050 Accelerometer',     'GY-521 at free tip. Z-axis over I²C captures vibration ring-down for FFT analysis.'],
    params:  ['Fixed Parameters',          'Beam constants hardcoded in firmware: b (width), h (thickness), L (length), E, I, c.'],
    arduino: ['Arduino Uno — DAQ',         'Polls sensors, subtracts strain offset, streams time + strain + acceleration at 115200 baud.'],
    static:  ['Static Pipeline',           'ε→σ (Hooke\'s law) →M (bending moment) →F (tip force) →m. RMSE ≈ 1.5 g, R² = 0.997.'],
    dynamic: ['Dynamic Pipeline',          'Remove DC from az, run FFT on ring-down, read dominant peak → natural frequency 5.83 Hz.'],
    csv:     ['CSV Output',                'Serial stream logged to CSV; post-processed in Python for calibration and FFT plots.']
  };

  var LINKS = {
    beam:    ['a-bs','a-ba'],
    strain:  ['a-bs','a-sard'],
    accel:   ['a-ba','a-aard'],
    params:  ['a-pard'],
    arduino: ['a-sard','a-aard','a-pard','a-ast','a-ady'],
    static:  ['a-ast','a-stc'],
    dynamic: ['a-ady','a-dyc'],
    csv:     ['a-stc','a-dyc']
  };

  var iT = svg.querySelector('#bd-it');
  var iD = svg.querySelector('#bd-id');

  function reset() {
    svg.querySelectorAll('.bng.lit').forEach(function (n) { n.classList.remove('lit'); });
    svg.querySelectorAll('.bar.lit,.bdar.lit').forEach(function (a) {
      a.classList.remove('lit');
      a.setAttribute('marker-end', a.classList.contains('bdar') ? 'url(#bd-dah)' : 'url(#bd-ah)');
    });
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover a block to see details';
  }

  svg.querySelectorAll('.bng').forEach(function (node) {
    var id = node.dataset.id;
    function on() {
      reset();
      node.classList.add('lit');
      (LINKS[id] || []).forEach(function (aid) {
        var a = svg.querySelector('#' + aid);
        if (a) { a.classList.add('lit'); a.setAttribute('marker-end','url(#bd-lah)'); }
      });
      var d = DESCS[id] || ['',''];
      if (iT) iT.textContent = d[0];
      if (iD) iD.textContent = d[1];
    }
    node.addEventListener('mouseenter', on);
    node.addEventListener('focus',      on);
    node.addEventListener('mouseleave', reset);
    node.addEventListener('blur',       reset);
    node.addEventListener('click', function (e) { e.stopPropagation(); on(); });
  });
  svg.addEventListener('click', reset);

  // ── Signal-flow draw-on animation ──────────────────────────
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    svg.querySelectorAll('.bar,.bdar').forEach(function (a) { a.style.opacity = 1; });
    return;
  }

  var FLOW = [
    ['a-bs','a-ba'],
    ['a-sard','a-aard','a-pard'],
    ['a-ast','a-ady'],
    ['a-stc','a-dyc']
  ];

  var t = 2000;
  FLOW.forEach(function (group) {
    group.forEach(function (id) {
      var el = svg.querySelector('#' + id);
      if (!el) return;
      setTimeout(function () {
        var len = el.getTotalLength ? el.getTotalLength() : 100;
        el.style.strokeDasharray  = len;
        el.style.strokeDashoffset = len;
        el.style.opacity = 1;
        requestAnimationFrame(function () {
          requestAnimationFrame(function () {
            el.style.transition = 'stroke-dashoffset 0.45s cubic-bezier(.4,0,.2,1)';
            el.style.strokeDashoffset = 0;
          });
        });
      }, t);
    });
    t += 480;
  });
})();
//
